  WHEN LOWER(ten_mon) LIKE LOWER('%nước suối%') THEN 'https://images.unsplash.com/photo-1544145945-f90425340c7e?w=500&q=80'
  WHEN LOWER(ten_mon) LIKE LOWER('%trà đá%') THEN 'https://images.unsplash.com/photo-1544145945-f90425340c7e?w=500&q=80'
  WHEN LOWER(ten_mon) LIKE LOWER('%rượu%') THEN 'https://images.unsplash.com/photo-1544145945-f90425340c7e?w=500&q=80'
  ELSE 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=500&q=80'
END
WHERE hinh_anh_dai_dien IS NULL;

SELECT CONCAT('Đã update ', ROW_COUNT(), ' ảnh món ăn') AS result;

-- ============================================================
-- 3. KIỂM TRA KẾT QUẢ
-- ============================================================
SELECT COUNT(*) AS tong_cua_hang, SUM(anh_dai_dien IS NOT NULL) AS co_anh, SUM(anh_dai_dien IS NULL) AS chua_co_anh FROM cua_hang;
SELECT COUNT(*) AS tong_mon_an, SUM(hinh_anh_dai_dien IS NOT NULL) AS co_anh, SUM(hinh_anh_dai_dien IS NULL) AS chua_co_anh FROM mon_an;